<?php
$stats = db()->query("SELECT COUNT(*) total, COALESCE(SUM(sex = 'Male'),0) male, COALESCE(SUM(sex = 'Female'),0) female, COALESCE(SUM(status = 'Active'),0) active, COALESCE(SUM(employment_status = 'Employed'),0) employed, COALESCE(SUM(employment_status = 'Unemployed'),0) unemployed FROM osy_records WHERE archived_at IS NULL")->fetch();
$recent = db()->query('SELECT * FROM osy_records WHERE archived_at IS NULL ORDER BY created_at DESC, id DESC LIMIT 5')->fetchAll();
$ageCounts = ['15–17' => 0, '18–20' => 0, '21–24' => 0, 'Other ages' => 0];
foreach (db()->query('SELECT birthdate FROM osy_records WHERE archived_at IS NULL') as $row) { $years = age($row['birthdate']); $group = $years >= 15 && $years <= 17 ? '15–17' : ($years >= 18 && $years <= 20 ? '18–20' : ($years >= 21 && $years <= 24 ? '21–24' : 'Other ages')); $ageCounts[$group]++; }
?>
<div class="page-heading"><div><div class="eyebrow">YOUR COMMUNITY AT A GLANCE</div><h1>Dashboard</h1><p>Welcome back. Here’s an overview of your registered youth.</p></div><a class="button primary" href="<?= e(url('register')) ?>"><span class="plus">+</span> Register OSY</a></div>
<section class="stats-grid" aria-label="Community statistics">
<?php foreach ([['total', 'Registered OSY', 'All community records', 'records', 'green'], ['male', 'Male', 'Registered male youth', 'records', 'blue'], ['female', 'Female', 'Registered female youth', 'records', 'purple'], ['active', 'Active OSY', 'Currently active records', 'idcards', 'orange']] as [$key, $label, $hint, $glyph, $color]): ?>
<article class="stat-card"><div class="stat-top"><span><?= e($label) ?></span><span class="stat-icon <?= $color ?>"><?= icon($glyph) ?></span></div><strong class="stat-number"><?= number_format((int)$stats[$key]) ?></strong><small><?= e($hint) ?></small></article>
<?php endforeach; ?></section>
<div class="dashboard-middle"><section class="panel age-panel"><div class="panel-heading"><div><h2>Youth by age group</h2><p>Understanding the ages in your community</p></div><span class="subtle-label">All registered OSY</span></div><div class="chart-area"><div class="chart-guide"><span><?= max(5, max($ageCounts)) ?></span><span><?= round(max(5, max($ageCounts))/2) ?></span><span>0</span></div><div class="bar-chart"><?php foreach ($ageCounts as $label => $count): ?><div class="bar-column"><div class="bar-track"><div class="bar" style="--bar-height: <?= max(2, $count / max(5, max($ageCounts)) * 100) ?>%"><span><?= $count ?></span></div></div><span class="bar-label"><?= e($label) ?></span></div><?php endforeach; ?></div></div><div class="chart-caption"><span class="legend-dot"></span> Number of registered youth <span>Age calculated from birthdate</span></div></section>
<section class="panel employment-panel"><div class="panel-heading"><div><h2>Employment overview</h2><p>A snapshot of current employment</p></div></div><div class="employment-total"><strong><?= number_format((int)$stats['total']) ?></strong><span>registered youth</span></div><div class="employment-bar"><span style="width:<?= $stats['total'] ? ($stats['employed'] / $stats['total'] * 100) : 0 ?>%"></span></div><div class="employment-row"><span><i class="legend-dot"></i> Employed</span><strong><?= $stats['employed'] ?><small><?= $stats['total'] ? round($stats['employed'] / $stats['total'] * 100) : 0 ?>%</small></strong></div><div class="employment-row"><span><i class="legend-dot pale"></i> Unemployed</span><strong><?= $stats['unemployed'] ?><small><?= $stats['total'] ? round($stats['unemployed'] / $stats['total'] * 100) : 0 ?>%</small></strong></div><a class="text-link employment-link" href="<?= e(url('reports')) ?>">View detailed report <?= icon('arrow') ?></a></section></div>
<section class="panel"><div class="panel-heading"><div><h2>Recent registrations</h2><p>The latest youth added to your records</p></div><a class="text-link" href="<?= e(url('records')) ?>">View all records <?= icon('arrow') ?></a></div><?php $rows = $recent; $compact = true; require __DIR__ . '/table.php'; ?></section>
<div class="quick-note"><span class="note-icon"><?= icon('idcards') ?></span><div><strong>A record today. An opportunity tomorrow.</strong><p>Keep profiles up to date and generate an ID card for every registered youth.</p></div><a href="<?= e(url('idcards')) ?>">Generate an ID <?= icon('arrow') ?></a></div>
